import {wheelSpeed,WHEEL_SPEEDS,reducedMotion} from './wheel-settings.js';
// Screen-sized type lives outside the rotating SVG. Dense full names appear at ×4.
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=p=>p===0?'不参与':p===1?'100%':(p*100>=.01?(p*100).toFixed(2).replace(/\.?0+$/,''):(p*100).toPrecision(2))+'%';
const xy=(a,r)=>[400+Math.cos(a*Math.PI/180)*r,400+Math.sin(a*Math.PI/180)*r];
const path=(a,b)=>{const p=xy(a,354),q=xy(b,354);return `M400 400 L${p.join(' ')} A354 354 0 ${b-a>180?1:0} 1 ${q.join(' ')} Z`;};
const shortLines=(text,count,title)=>{const s=String(text).split('（')[0];if(count>20)return [s.length>6?s.slice(0,5)+'…':s];if(title==='成长天赋'){const [grade,other='']=s.split(' · ');return [grade,...other.split(' ')];}if(count===17&&s.includes(' · ')){const [grade,other]=s.split(' · ');return [grade,other.split('·')[0]];}return s.match(/.{1,5}/gu)||[s];};
export function spinAngle(t,finish){
 t=Math.max(0,Math.min(1,t));if(t===1)return finish;const ramp=.12,cruise=.4,tail=1-cruise,area=ramp/2+cruise-ramp+tail/3;
 if(t<ramp)return finish*t*t/(2*ramp*area);
 if(t<cruise)return finish*(ramp/2+t-ramp)/area;
 const p=(t-cruise)/tail;return finish*(ramp/2+cruise-ramp+tail*(1-(1-p)**3)/3)/area;
}
export function pointerIndex(angle,count){return ((Math.round(-angle/(360/count))%count)+count)%count;}
export function wheelMarkup({options,title,result='',selected='',rolling=false,duration=3900,speed=wheelSpeed()}){
 const n=options.length,chosen=options.findIndex(o=>o.id===String(selected)),finish=2160-Math.max(0,chosen)*360/n,dense=n>40,hiddenResult=!rolling&&chosen>=0&&!!options[chosen].hidden;
 const sectors=options.map((o,i)=>{const a=-90+i*360/n,lines=shortLines(o.label,n,title),label=dense?`<text class="sector-name dense-name" x="741" y="400" text-anchor="end" dominant-baseline="middle" font-size="9">${esc(String(o.label).split("（")[0].length>9?String(o.label).split("（")[0].slice(0,8)+"…":String(o.label).split("（")[0])}</text>${i%Math.ceil(n/12)===0?`<text class="sector-index" x="725" y="400" text-anchor="end" dominant-baseline="middle" font-size="30">${String(i+1).padStart(3,'0')}</text>`:''}`:lines.map((line,j)=>`<text class="sector-name" x="723" y="${400+(j-(lines.length-1)/2)*35}" text-anchor="end" dominant-baseline="middle" font-size="${n>20?30:32}">${esc(line)}</text>`).join('');return `<g class="wheel-sector ${o.probability===0?'inactive':''} ${!rolling&&i===chosen?'selected':''}" data-option-id="${esc(o.id)}"><title>${esc(o.label)} · ${pct(o.probability)}</title><path d="${path(a-180/n,a+180/n)}" fill="${o.color}"/><g transform="rotate(${a} 400 400)">${label}</g></g>`;}).join('');
 const ticks=Array.from({length:120},(_,i)=>{const p=xy(i*3,i%5?369:362),q=xy(i*3,377);return `<path d="M${p.join(' ')} L${q.join(' ')}" stroke="${i%5?'#bdd3da70':'#eff9fc'}" stroke-width="${i%5?1:2}"/>`;}).join('');
 const bolts=Array.from({length:8},(_,i)=>{const p=xy(i*45+22.5,389);return `<g transform="translate(${p.join(' ')})"><circle r="3.5" fill="#9aaeb7"/><path d="M-2 0H2" stroke="#18262f"/></g>`;}).join('');
 return `<section class="fate-wheel ${rolling?'is-spinning':''} ${dense?'dense-wheel':''}" aria-label="${esc(title)}转盘" data-count="${n}" data-duration="${duration}" data-finish="${finish}" data-chosen="${chosen}"><div class="wheel-presentation"><div class="wheel-tools"><span>命运转盘 <b>${n} 项</b></span><div role="group" aria-label="转盘速度"><button type="button" data-act="wheelMotion" ${rolling?'disabled':''}>${reducedMotion()?'完整动效':'简化动效'}</button><span class="wheel-speed-label">速度</span>${WHEEL_SPEEDS.map(z=>`<button type="button" data-act="wheelSpeed:${z}" aria-label="转盘速度 ×${z}" aria-pressed="${z===speed}" ${rolling?'disabled':''}>×${z}</button>`).join('')}</div></div><div class="wheel-viewport" tabindex="0" aria-label="转盘，放大后可滚动查看"><div class="wheel-assembly"><svg class="wheel-rim" viewBox="0 0 800 800" aria-hidden="true"><defs><linearGradient id="metal19" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b7c5cc"/><stop offset=".23" stop-color="#324958"/><stop offset=".45" stop-color="#8096a3"/><stop offset=".72" stop-color="#1b303d"/><stop offset="1" stop-color="#95adb8"/></linearGradient></defs><circle cx="400" cy="400" r="397" fill="url(#metal19)"/><circle cx="400" cy="400" r="381" fill="#0e1d28" stroke="#0a131b" stroke-width="4"/>${bolts}</svg><div class="wheel-rotor" style="transform:rotate(${rolling?0:finish}deg)"><svg class="wheel-face" viewBox="0 0 800 800" aria-hidden="true">${sectors}<circle cx="400" cy="400" r="352" class="sector-edge"/><circle cx="400" cy="400" r="300" class="etched-ring"/>${ticks}<path d="M400 43L408 57L392 57Z" fill="#e5f4f7"/></svg></div><div class="wheel-pin"><i></i></div><div class="wheel-hub"><span>PRTS / ${esc(title)}</span><strong>${rolling?'···':chosen>=0?String(chosen+1).padStart(3,'0'):'—'}</strong><small>${rolling?'转动中':chosen>=0?(hiddenResult?'已抽取 · 隐藏':'已抽取'):'等待转动'}</small></div><div class="wheel-light"></div></div></div><div class="wheel-readout ${!rolling&&chosen>=0?'revealed':''}" role="status" aria-live="polite"><span class="readout-pool" ${hiddenResult?'':'hidden'}>隐藏</span><span class="readout-label">${rolling?'正在加速':chosen>=0?'抽取结果':'尚未抽取'}</span><strong class="readout-name">${rolling?'指针开始拨动…':esc(result||'点击下方按钮，让命运转动')}</strong><button type="button" class="restore-result" hidden>返回抽取结果</button></div><div class="spin-progress" role="progressbar" aria-label="转盘进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${rolling?0:100}"><i style="width:${rolling?0:100}%"></i></div><p class="wheel-note">${dense?'使用“放大读字”查看盘面简称；完整名称见列表。':'指针所指扇区即为抽取结果。'}扇区等宽，概率见列表。 <button type="button" class="wheel-detail" data-wheel-detail aria-label="放大盘面读字" aria-pressed="false" ${rolling?'disabled':''}>放大读字</button></p></div><details class="wheel-catalog" open><summary><strong>全部选项</strong><span>${n} 项${options.some(o=>o.hidden)?' · 隐藏 '+options.filter(o=>o.hidden).length:''}</span><i>⌄</i></summary><div class="catalog-body">${dense?'<input type="search" class="wheel-search" placeholder="搜索名称或原型" aria-label="搜索转盘选项">':''}<ol class="wheel-options">${options.map((o,i)=>`<li class="${!rolling&&i===chosen?'picked':''} ${o.probability===0?'unavailable':''}" data-label="${esc(o.label)}" data-hidden="${o.hidden?'true':'false'}" data-option-id="${esc(o.id)}"><button type="button" data-wheel-inspect="${i}" ${rolling?'disabled':''} aria-label="查看${esc(o.label)}"><i style="--chip:${o.color}"></i><span><small>${String(i+1).padStart(3,'0')}${o.hidden?' · 隐藏':''}</small><b>${esc(o.label)}</b></span><em>${pct(o.probability)}</em></button></li>`).join('')}</ol><p class="wheel-empty" hidden>没有匹配的选项，请换一个名称。</p></div></details></section>`;
}
export function bindWheels(root){
 for(const wheel of root.querySelectorAll('.fate-wheel')){
  const viewport=wheel.querySelector('.wheel-viewport'),assembly=wheel.querySelector('.wheel-assembly'),rotor=wheel.querySelector('.wheel-rotor'),rows=[...wheel.querySelectorAll('.wheel-options li')],name=wheel.querySelector('.readout-name'),label=wheel.querySelector('.readout-label'),chosen=Number(wheel.dataset.chosen),result=name.textContent,pool=wheel.querySelector('.readout-pool'),resultHidden=!pool.hidden;
  if(matchMedia('(max-width:760px)').matches)wheel.querySelector('details').open=false;
  wheel.querySelector('[data-wheel-detail]')?.addEventListener('click',e=>{const button=e.currentTarget,zoom=wheel.dataset.zoom==='4'?1:4;assembly.style.width=zoom===1?'100%':viewport.clientWidth*zoom+'px';wheel.dataset.zoom=String(zoom);button.setAttribute('aria-pressed',String(zoom===4));button.setAttribute('aria-label',zoom===4?'还原盘面尺寸':'放大盘面读字');button.textContent=zoom===4?'还原盘面':'放大读字';viewport.scrollLeft=(assembly.clientWidth-viewport.clientWidth)/2;viewport.scrollTop=0;});
  wheel.querySelector('.wheel-search')?.addEventListener('input',e=>{let count=0;for(const row of rows){row.hidden=!row.dataset.label.toLocaleLowerCase().includes(e.target.value.trim().toLocaleLowerCase());if(!row.hidden)count++;}wheel.querySelector('.wheel-empty').hidden=count>0;});
  const restore=wheel.querySelector('.restore-result');restore.addEventListener('click',()=>{name.textContent=result;pool.hidden=!resultHidden;label.textContent=chosen>=0?'抽取结果':'尚未抽取';restore.hidden=true;wheel.querySelectorAll('.inspected').forEach(e=>e.classList.remove('inspected'));});
  wheel.querySelectorAll('[data-wheel-inspect]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.wheelInspect);name.textContent=rows[i].dataset.label;pool.hidden=rows[i].dataset.hidden!=='true';label.textContent='浏览选项 · 不改变抽取结果';restore.hidden=false;wheel.querySelectorAll('.inspected').forEach(e=>e.classList.remove('inspected'));rows[i].classList.add('inspected');wheel.querySelectorAll('.wheel-sector')[i].classList.add('inspected');}));
  if(!wheel.classList.contains('is-spinning')){const picked=wheel.querySelector('.picked'),list=wheel.querySelector('.wheel-options');if(picked)list.scrollTop=picked.offsetTop-list.offsetTop;continue;}
  const finish=Number(wheel.dataset.finish),duration=Number(wheel.dataset.duration),start=performance.now(),pin=wheel.querySelector('.wheel-pin'),progress=wheel.querySelector('.spin-progress'),bar=progress.querySelector('i');let last=-1,lastTick=0,lastName=0;
  function frame(now){if(!wheel.isConnected)return;const t=Math.min(1,(now-start)/duration),angle=spinAngle(t,finish),index=pointerIndex(angle,rows.length);rotor.style.transform=`rotate(${angle}deg)`;wheel.dataset.rotation=angle.toFixed(3);wheel.dataset.spinPhase=t<.12?'accelerating':t<.4?'cruising':t<.95?'braking':'settling';bar.style.width=t*100+'%';progress.setAttribute('aria-valuenow',String(Math.round(t*100)));
   if(index!==last&&now-lastTick>65){pin.classList.remove('pointer-tick');void pin.offsetWidth;pin.classList.add('pointer-tick');lastTick=now;last=index;}
   if(now-lastName>100){label.textContent=t<.12?'正在加速':t<.4?'转盘运转':t<.95?'正在减速':'即将揭晓';name.textContent='经过：'+rows[index].dataset.label;lastName=now;}
   if(t<1)requestAnimationFrame(frame);
  }requestAnimationFrame(frame);
 }
}
